/**
 * The Plinth version written at the top of every generated file, and the date of that version. They are bumped together by
 * hand when the generator changes (a test keeps the version equal to package.json). They are constants, not a stamp made at
 * build or export time, so exporting, importing and exporting again always gives byte identical files.
 */
export const PLINTH_VERSION = "0.2.0";
export const PLINTH_VERSION_DATE = "2026-11-16";
